-- The two checklists published on 2026-11-06: Settling in a Country That Is
-- Not Yours (Immigration) and Growing Something From Seed (Gardening).
-- Generated by `python3 tools/checklists_sql.py --since 2026-11-06`; the repo
-- copy in data/checklists.json is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('settling-in-a-country-that-is-not-yours', 'Settling in a Country That Is Not Yours', 'For the first year or two in a new country, when everything takes longer and nothing is automatic. It keeps the paperwork in one place, learns the sentences you actually use, finds the food you grew up on, and gives the clumsy stage the time it needs.', 'Immigration', '["Keep your documents in one place you can grab fast — paperwork panic is its own kind of exhausting.", "Learn ten sentences you will actually use this week — the bakery and the bus matter more than grammar.", "Find one shop that sells the food you grew up on — a familiar taste is not a weakness.", "Say yes to one invitation a week even when tired — belonging gets built out of small attendances.", "Set a fixed hour to call home — open-ended longing is heavier than a standing date.", "Ask someone to explain one thing you pretended to follow — nobody grades you for asking twice.", "Find out who helps new arrivals near you — a library, a church, a community center, a group chat.", "Give yourself two years rather than two months — the clumsy stage is long and it is not failure.", "Write down one thing that went well each week — early on, the hard parts are much louder than the wins."]'::jsonb, 'weekly', array['Life Transitions', 'Loneliness', 'Resilience']::text[], 1, '2026-11-06T16:00:00+00:00'::timestamptz),
  ('growing-something-from-seed', 'Growing Something From Seed', 'For anyone who wants to grow something and does not know where to start. It keeps the plot small, picks plants that come up fast, puts them where you walk past, ties watering to a fixed hour, and lets a dead plant be information.', 'Gardening', '["Start with three pots rather than a whole bed — a small plot you tend beats a big one you abandon.", "Pick something fast, like radishes or basil — early proof is what keeps you coming back out.", "Put the pots where you already walk past — out of sight is the main cause of death here.", "Water at the same time of day — a fixed hour does the remembering for you.", "Push a finger into the soil before watering — dry on top is not dry underneath.", "Write the planting date on a stick — four weeks of nothing is normal and easy to forget.", "Let something die without taking it personally — a lost plant is information, not a verdict.", "Go out for two minutes with no job to do — looking at it is half of why you did this.", "Give one cutting away when something takes off — a plant passed on is the whole point."]'::jsonb, 'weekly', array['Self-Care', 'Mindfulness', 'Motivation']::text[], 1, '2026-11-06T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
